<?php
declare(strict_types=1); require_once __DIR__.'/product_auth.php'; $pdo=db(); $id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Product not found.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sku=trim($_POST['sku']??'');$name=trim($_POST['name']??'');$description=trim($_POST['description']??'');$price=trim($_POST['price']??'');if($sku==='')$errors[]='SKU is required.';if($name==='')$errors[]='Product name is required.';if($price===''||!is_numeric($price)||(float)$price<0)$errors[]='Enter a valid price.';if(!$errors){$s=$pdo->prepare('SELECT id FROM products WHERE sku=? AND id<>?');$s->execute([$sku,$id]);if($s->fetch())$errors[]='This SKU already exists.';else{$s=$pdo->prepare('UPDATE products SET sku=?,name=?,description=?,price=? WHERE id=?');$s->execute([$sku,$name,$description?:null,number_format((float)$price,2,'.',''),$id]);header('Location: products.php?success=Product%20updated%20successfully.');exit;}}$product['sku']=$sku;$product['name']=$name;$product['description']=$description;$product['price']=$price;}
$pageTitle='Edit Product';require __DIR__.'/header.php';?><div class="card"><h1>Edit Product</h1><?php foreach($errors as $x): ?><div class="alert error"><?= e($x) ?></div><?php endforeach; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>SKU ID<input name="sku" required value="<?= e($product['sku']) ?>"></label><label>Product Name<input name="name" required value="<?= e($product['name']) ?>"></label><label>Price<input type="number" name="price" min="0" step="0.01" required value="<?= e((string)$product['price']) ?>"></label><label>Description<textarea name="description" rows="5"><?= e($product['description']) ?></textarea></label><button type="submit">Save Changes</button><a class="button secondary" href="products.php">Cancel</a></form></div><?php require __DIR__.'/footer.php'; ?>
